namespace PropTest.Desktop;

public sealed record ErrorExplanation(string Title, string Guidance)
{
    public static ErrorExplanation From(string text)
    {
        if (text.Contains("не передає виміри датчиків", StringComparison.Ordinal))
            return new("Запис вимірів недоступний", "Датчики в цій прошивці ще не активовані. Для версії 0.3 короткий тест GPIO14 відкривається кнопкою «Плата: оновлення й тест» на вкладці «Підключення».");
        if (text.Contains("Wi-Fi:", StringComparison.Ordinal))
            return new("Немає зв’язку через Wi-Fi", "Перевірте живлення плати й адресу в мережі вашого роутера. Ноутбук може залишатися у звичайній Wi-Fi мережі. Запасний варіант — власна мережа PROpTEST-v2 з адресою 192.168.4.1; її пароль доступний через USB.");
        if (text.StartsWith("Втрачено зв’язок із платою", StringComparison.Ordinal))
            return new("ESP32-S3 перестала відповідати", "Перевірте живлення й USB-кабель або Wi-Fi мережу плати. USB визначається автоматично; для Wi-Fi натисніть «Перевірити з’єднання». Тест мотора автоматично не відновлюється.");
        if (text.StartsWith("Не вдалося зберегти CSV:", StringComparison.Ordinal))
            return new("CSV не збережено", "Не вдалося записати файл у вибране місце. Перевірте доступ до папки, вільне місце та чи не відкрито цей файл в іншій програмі. Потім повторіть експорт або виберіть іншу папку.\n\nЗапис експерименту залишається в архіві. Причина помилки наведена в технічних деталях.");
        if (text.Contains("Аварійна зупинка за тягою завершила тест", StringComparison.Ordinal))
            return new("Тест зупинено через різку зміну тяги", "За сталого газу два послідовні виміри тяги вийшли за налаштовані пороги. Програма надіслала Stop і зберегла запис.\n\nПеревірте кріплення, пропелер і датчик тяги. Якщо причина — особливість вашого тесту, до нового запуску змініть пороги або вимкніть «Аварійна зупинка за тягою». Це додатковий контроль через ПК, не незалежний апаратний захист.");
        if (text.Contains("сигнал датчика струму відсутній", StringComparison.Ordinal))
            return new("Запуск заблоковано датчиком струму", "Arduino відповідає, але сигнал струму відсутній, виходить за діапазон або його оцінка досягла 8 А. Газ скинуто в нуль.\n\nПеревірте живлення датчика ACS712, спільний GND і сигнал до A3. Перед перевіркою проводів відключіть акумулятор ESC. Повторіть підключення після усунення причини. Номінальна формула датчика ще потребує калібрування.");
        if (text.Contains("обмежує газ до 30%", StringComparison.Ordinal))
            return new("Ліміт цієї плати — 30%", "У прошивці встановлено обмеження 30%. Увімкніть «Обмежувати газ» і встановіть ліміт не вище 30%, потім повторіть запис. Зняття галочки не скасовує обмеження Arduino.");
        if (text.Contains("не отримувала heartbeat", StringComparison.Ordinal))
            return new("Arduino зупинила газ через втрату зв’язку", "Протягом секунди плата не отримувала сигнал присутності програми. Вона скинула газ у нуль.\n\nПеревірте USB-з’єднання й натисніть «Підключити» перед наступним записом. Попередня команда газу автоматично не відновлюється.");
        if (text.StartsWith("Не вказано назву тесту", StringComparison.Ordinal))
            return new("Вкажіть назву тесту", "Поле назви порожнє, тому запис не розпочато.\n\nВідкрийте «Налаштування тесту» зліва та заповніть поле «Назва тесту», наприклад «Мотор 2807 — перевірка 1». Потім натисніть «Почати тест».");
        if (text.StartsWith("Назва тесту задовга", StringComparison.Ordinal))
            return new("Скоротіть назву тесту", "Назва перевищує 120 символів.\n\nУ «Налаштуваннях тесту» скоротіть поле «Назва тесту» та повторіть запуск запису.");
        if (text.StartsWith("Оберіть COM-порт", StringComparison.Ordinal))
            return new("Не вибрано пристрій", "Програма ще не знає, до якого USB-пристрою підключатися. COM-порт — це назва його каналу зв’язку у Windows.\n\nПідключіть Arduino USB-кабелем. Відкрийте вкладку «Підключення», натисніть «Оновити COM-порти», оберіть порт плати та натисніть «Підключити». Якщо список порожній, перевірте кабель і USB-підключення.");
        if (text.StartsWith("Порт не відповів", StringComparison.Ordinal))
            return new("Пристрій не відповів", "USB-порт відкрився, але прошивка на платі не відповіла на запит PROpTEST. Наявність Arduino у Windows підтверджує USB-підключення, але не готовність її програми.\n\nУ «Підключенні» перевірте вибраний порт. Закрийте Arduino Serial Monitor та інші програми, які використовують плату, і повторіть підключення. Якщо помилка залишається, потрібно перевірити, яку прошивку завантажено, і чи завершується її запуск. Стара прошивка могла блокуватися на запуску датчиків. Нова PT:2.0 відповідає навіть за відсутності їхніх даних. Зміна номера COM сама по собі цього не виправить.");
        if (text.StartsWith("Не вдалося відкрити COM-порт", StringComparison.Ordinal))
            return new("Не вдалося відкрити підключення", "Можливо, плату від’єднано, обраний порт змінився або його використовує інша програма.\n\nПеревірте USB-кабель, закрийте Serial Monitor, потім у вкладці «Підключення» оновіть список портів і виберіть плату знову. Точне повідомлення системи є нижче у технічних деталях.");
        if (text.StartsWith("Спочатку підключіть пристрій", StringComparison.Ordinal) || text.StartsWith("COM-порт не підключено", StringComparison.Ordinal))
            return new("Пристрій не підключено", "Запис вимірів не можна почати без джерела даних.\n\nВідкрийте «Підключення», оберіть порт Arduino та натисніть «Підключити». Для перевірки програми без плати увімкніть там «Симулятор» і підключіть його.");
        if (text.StartsWith("Втрачено телеметрію", StringComparison.Ordinal))
            return new("Дані від пристрою перестали надходити", "Тест перервано через відсутність нових вимірів. Це може бути обрив USB або збій плати.\n\nДля реального стенда перевірте, що мотор зупинився: стара прошивка може залишити його увімкненим після обриву USB. За потреби відключіть живлення ESC. Потім перевірте кабель і повторіть підключення у вкладці «Підключення».");
        if (text.StartsWith("Інтервал:", StringComparison.Ordinal))
            return new("Перевірте інтервал вимірів", "У «Налаштуваннях тесту» задайте «Інтервал вимірів» від 50 до 2000 мс. Наприклад, 200 мс — приблизно п’ять вимірів за секунду.");
        if (text.StartsWith("Ліміт газу:", StringComparison.Ordinal))
            return new("Перевірте ліміт газу", "У полі «Ліміт, %» зліва потрібно вказати число від 1 до 100. Змініть його перед початком запису.");
        if (text.StartsWith("Тривалість:", StringComparison.Ordinal))
            return new("Перевірте час тесту", "У «Налаштуваннях тесту» задайте «Максимальний час» від 1 до 7200 секунд, наприклад 60 секунд.");
        return new("Сталася помилка", "Програма не змогла завершити операцію. Точну причину не визначено.\n\nРозгорніть «Технічні деталі» нижче: там збережене початкове повідомлення. Його можна передати для діагностики або використати для пошуку рішення.");
    }
}





